# TEMPLATE generated by Hagane Works.
# STARTING POINT — adjust positions/sprites/variables and VERIFY IN-GAME.
# Numeric variables are shown via [?var|N] inside generated localisation. If you add a
# close button, its clickable hitbox MUST come from a buttonType's
# quadTextureSprite (a bare spriteType renders but isn't clickable) — see the
# Hagane Works superevent template for the working idiom.
guiTypes = {

	containerWindowType = {
		name = "my_panel_window"
		orientation = upper_right
		Origo = upper_right
		size = { width = 420 height = 144 }
		position = { x = -20 y = 120 }
		moveable = yes

		background = {
			name = "Background"
			quadTextureSprite = "GFX_tiled_window_transparent"
		}

		instantTextBoxType = {
			name = "my_panel_title"
			position = { x = 0 y = 16 }
			font = "hoi_30header"
			text = "my_panel_TITLE"
			maxWidth = 420
			maxHeight = 36
			fixedsize = yes
			format = center
		}

		instantTextBoxType = {
			name = "my_panel_row_0"
			position = { x = 24 y = 64 }
			font = "hoi_18mbs"
			text = "my_panel_ROW_0"
			maxWidth = 372
			maxHeight = 24
		}

		instantTextBoxType = {
			name = "my_panel_row_1"
			position = { x = 24 y = 92 }
			font = "hoi_18mbs"
			text = "my_panel_ROW_1"
			maxWidth = 372
			maxHeight = 24
		}
	}
}

# TEMPLATE generated by Hagane Works.
# Binds my_panel.gui. context_type = player_context shows it for the human player;
# `visible = always` shows it unconditionally — GATE this with your own trigger
# (e.g. `tag = FNG` or `has_country_flag = ...`) so it only appears for the
# relevant country. [?var] text updates live, so no `dirty` refresh is needed for
# a read-only overview.
scripted_gui = {
	my_panel = {
		context_type = player_context
		window_name = "my_panel_window"

		visible = {
			always = yes
		}
	}
}

# TEMPLATE generated by Hagane Works.
# STARTING POINT — fill the effect block(s) and VERIFY IN-GAME.
# on_actions MERGES additively across files, so this NEW file is added to the
# base mod's hooks (it does NOT replace them). Each hook below fires its
# `effect = { ... }` at the matching game moment. Real hook tokens include
# on_startup, on_monthly, on_weekly, on_daily, on_government_change,
# on_capitulation, on_war, etc. — see common/on_actions/00_on_actions.txt.
# DELETE the hooks you don't need; an empty effect block is a harmless no-op.
on_actions = {

	on_startup = {
		effect = {
			# Fired once when the game / save starts. Scope is no country —
			# use `every_country`, a TAG scope, or `random_country` inside.
			# Example:
			# GER = { set_country_flag = my_hooks_started }
		}
	}

	on_monthly = {
		effect = {
			# Fired once per in-game month, scoped to each country in turn
			# (ROOT = the country being pulsed). GATE with a `limit` /
			# `if = { limit = { ... } ... }` so it only runs where relevant.
			# Example:
			# if = { limit = { tag = GER } add_political_power = 5 }
		}
	}
}

# TEMPLATE generated by Hagane Works.
# STARTING POINT — set the strategy type/id/value rows and VERIFY IN-GAME.
# `allowed` gates WHICH country this block applies to (original_tag = GER);
# `enable` is a trigger re-checked over time (always = yes = always on).
# Each `ai_strategy = { type = X id = Y value = N }` row nudges the AI — the
# valid `type` tokens (befriend, conquer, role_ratio, build_army, ignore, …)
# and what `id` means depend on the type. See common/ai_strategy/*.txt
# (e.g. ENG.txt) for working rows to copy.
my_strat_strategy = {

	allowed = { original_tag = GER }
	enable = {
		always = yes
	}
	abort_when_not_enabled = yes

	# Example row — replace type/id/value with a real strategy:
	ai_strategy = {
		type = role_ratio
		id = garrison
		value = 5
	}
}

# TEMPLATE generated by Hagane Works (domain: common/bop).
# STARTING POINT — rename the sides/ranges, set real modifiers + icons, and VERIFY IN-GAME.
# A balance of power shows NOTHING until a script activates it on a country:
#   set_power_balance = { id = my_bop_balance }
# (fire that from a focus completion_reward / event option / on_action), then push it with
#   add_power_balance_value = { id = my_bop_balance value = 0.05 }
# The bar/side names read localisation keys (the BoP id + side/range ids).
# Hagane Works emits language-specific YML companions for every generated key.
# `icon` must be an existing sprite (interface/*.gfx); GFX_idea_unknown always exists.
# Vanilla covers the FULL [-1, 1] with ranges (centre + one per side) — keep it covered
# so every value the bar can reach lands in a range.
my_bop_balance = {
	initial_value = 0
	left_side = my_bop_left
	right_side = my_bop_right
	# Optional: pull a decision category into the balance-of-power view:
	# decision_category = my_bop_decisions

	range = {
		id = my_bop_centre
		min = -0.1
		max = 0.1
		# The centre range is deliberately neutral — no modifier.
	}

	side = {
		id = my_bop_left
		icon = GFX_idea_unknown
		range = {
			id = my_bop_left_range
			min = -1
			max = -0.1
			modifier = {
				# Mild placeholder — replace with this side's real effects.
				stability_weekly = 0.001
			}
		}
	}

	side = {
		id = my_bop_right
		icon = GFX_idea_unknown
		range = {
			id = my_bop_right_range
			min = 0.1
			max = 1
			modifier = {
				war_support_weekly = 0.001
			}
		}
	}
}

guiTypes = {
	containerWindowType = {
		name = "gamesetup_scenario_window"
		containerWindowType = {
			name = "bookmarks"
			gridBoxType = {
				name = "bookmarks_grid"
				slotsize = {
					width = 240
					height = 120
				}
			}
		}
	}
	containerWindowType = {
		name = "other_window"
	}
}
